'use strict';

/**
 * We are not using the built-in url module, because when it parse
 * an url, it escapes some characters like quoutes and asteriks, but we need the url
 * to be forwarded as it came to us.
 */
const _ = require('lodash');
const urijs = require('urijs');
const url = require('url');
const path = require('path');
const { VError } = require('verror');
const cookie = require('cookie');

const SAP_IDP_QUERY_PARAM = 'sap_idp';

module.exports = {
  SAP_IDP_QUERY_PARAM: SAP_IDP_QUERY_PARAM,
  parse: function (urlString) {
    const parsedUri = urijs.parse(urlString);

    const resultUrl = {
      protocol: parsedUri.protocol ? parsedUri.protocol + ':' : null,
      hostname: parsedUri.hostname || null,
      host: buildHost(parsedUri),
      port: parsedUri.port ? parsedUri.port : null,
      pathname: parsedUri.path,
      slashes: true,
      auth: buildUserInfo(parsedUri),
      search: parsedUri.query ? ('?' + parsedUri.query) : null,
      query: parsedUri.query ? parsedUri.query : null,
      hash: parsedUri.fragment ? ('#' + parsedUri.fragment) : null
    };

    resultUrl.path = resultUrl.pathname + (resultUrl.search || '');

    resultUrl.href = resultUrl.protocol ? (resultUrl.protocol + '//') : '';
    resultUrl.href += resultUrl.auth ? (resultUrl.auth + '@') : '';
    resultUrl.href += resultUrl.host ? resultUrl.host : '';
    resultUrl.href += resultUrl.path;
    resultUrl.href += resultUrl.hash ? resultUrl.hash : '';

    return resultUrl;
  },

  getFirstUrlSegment: function(req, useLocationAfterLogin) {
    const receivedAppKey = req && req.headers && req.headers['x-application-key'] && { url: req.headers['x-application-key'] };
    if (receivedAppKey) {
      return receivedAppKey;
    }
    const isLoginCallback = req && req.query && req.query.code && req.url.includes('login/callback');
    const cookies = isLoginCallback && useLocationAfterLogin && req && req.headers['cookie'] ? cookie.parse(req.headers['cookie']) : null;
    return cookies && cookies.locationAfterLogin ? { url: cookies.locationAfterLogin } : req;
  },

  buildAppRouterUrl: function (req) {
    const allowedProtos = ['http', 'https'];
    const reqHeaders = req.headers;
    const forwardedProtocol = reqHeaders['x-forwarded-proto'];
    const host = getRedirectHost(req);
    if (process.env.ACCEPTED_FORWARD_PROTOCOLS) {
      allowedProtos.push(process.env.ACCEPTED_FORWARD_PROTOCOLS);
    }
    if (forwardedProtocol && !allowedProtos.includes(forwardedProtocol)) {
      const error = new VError('Invalid request protocol: ' + forwardedProtocol);
      error.status = 400;
      throw error;
    }
    if (forwardedProtocol) {
      return forwardedProtocol + '://' + host;
    }

    const hostHeaderParts = host.split(':');
    if (hostHeaderParts.length === 2) {
      const port = hostHeaderParts[1];
      if (port === '443') {
        return 'https://' + host;
      }
      if (port === '80') {
        return 'http://' + host;
      }
    }
    return req.protocol + '://' + host;
  },

  getQueryParam: function (req, paramName, remove) {
    let params = this.getAllQueryParams(req);
    if (params && params[paramName] && remove === true) {
      req.url = this.removeQueryParam(req, paramName);
    }
    return params && params[paramName];
  },

  getAllQueryParams: function (req) {
    return req && req.url && (url.parse(req.url, true)).query;
  },

  removeQueryParamFromUrl: function (urlStr, paramName) {
    if (!urlStr) {
      return null;
    }
    const hashIdx = urlStr.indexOf('#');
    const fragment = hashIdx >= 0 ? urlStr.slice(hashIdx) : '';
    const withoutFragment = hashIdx >= 0 ? urlStr.slice(0, hashIdx) : urlStr;
    const qIdx = withoutFragment.indexOf('?');
    if (qIdx < 0) {
      return urlStr;
    }
    const base = withoutFragment.slice(0, qIdx);
    const newQuery = withoutFragment.slice(qIdx + 1)
      .split('&')
      .filter(function (part) {
        return part.split('=', 1)[0] !== paramName;
      })
      .join('&');
    return base + (newQuery ? '?' + newQuery : '') + fragment;
  },

  removeQueryParam: function (req, paramName) {
    if (req) {
      return this.removeQueryParamFromUrl(req.url, paramName);
    }
    return null;
  },

  getAppRouterHost: getAppRouterHost,
  getRedirectHost: getRedirectHost,
  addUUIDDashes: addUUIDDashes,

  join: function (url, path) {
    return _.trimEnd(url, '/') + '/' + _.trimStart(path, '/');
  },

  isRelativeUrl: function (location, strict = true) {
    if (strict) {
      if (typeof location !== 'string' || !location.startsWith('/') || location.startsWith('//') || location.startsWith('/\\')) {
        return false;
      }
      return true;
    }
    const parsedUrl = url.parse(location);
    return !(parsedUrl.host || parsedUrl.protocol);
  },

  validatePathname: function (req) {
    const MAX_DECODE_ITERATIONS = 5;
    if (req.url) {
      try {
        const urlPath = this.parse(req.url);
        let decodedPath = urlPath.pathname;
        let prev;
        let iterations = 0;
        do {
          if (iterations >= MAX_DECODE_ITERATIONS) {
            return new VError(
              'Failed to validate path, potential path traversal received:%s normalized:%s',
              decodedPath, path.posix.normalize(decodedPath));
          }
          prev = decodedPath;
          decodedPath = decodeURIComponent(decodedPath);
          iterations++;
        } while (decodedPath !== prev);
        decodedPath = decodedPath.normalize('NFKC');
        const sanitizedSlashes = decodedPath.replace(/\/{2,}/g, '/');
        const normalizedPath = path.posix.normalize(sanitizedSlashes).
          replace(/^(\.\.[\/\\])+/, '');
        if (normalizedPath !== sanitizedSlashes) {
          return new VError(
            'Failed to validate path, potential path traversal received:%s normalized:%s',
            decodedPath, normalizedPath);
        }
        return null;
      } catch (err) {
        return new VError('Failed to validate path, decode URI component:' + err.message);
      }
    } else {
      return new VError(
        'Failed to validate path, undefined');
    }
  }
};

function getRedirectHost(req) {
  const reqHeaders = req.headers;
  return reqHeaders['x-forwarded-host'] || reqHeaders.host || reqHeaders[':authority'];
}

function getAppRouterHost(req) {
  const reqHeaders = req.headers;
  const extReverseProxy = process.env.EXTERNAL_REVERSE_PROXY && (process.env.EXTERNAL_REVERSE_PROXY === 'true' || process.env.EXTERNAL_REVERSE_PROXY === true);
  if (extReverseProxy){
    return reqHeaders['x-custom-host'] ||  reqHeaders.host || reqHeaders[':authority'];
  }
  return reqHeaders['x-forwarded-host'] ||  reqHeaders.host || reqHeaders[':authority'];
}

function buildHost(parsedUri) {
  let host = parsedUri.hostname ? parsedUri.hostname : null;
  if (host && parsedUri.port) {
    host += ':' + parsedUri.port;
  }
  return host;
}

function buildUserInfo(parsedUri) {
  let res = '';
  if (typeof parsedUri.username === 'string') {
    res = parsedUri.username;
  }
  if (typeof parsedUri.password === 'string') {
    res += ':' + parsedUri.password;
  }
  return res || null;
}

function addUUIDDashes(uuid){
  if (uuid.indexOf('-') < 0){
    uuid = uuid.substr(0,8) + '-' + uuid.substr(8,4) + '-' + uuid.substr(12,4) + '-' + uuid.substr(16,4) + '-' + uuid.substr(20);
  }
  return uuid;
}

